import {defs,shadow,legacyScene,pitcher,steam} from './art.js';
let serial=0;
const legacy={grind:0,water:1,basket:2,assemble:3,heat:4,froth:5};
function glass(state,c){const vol=state.coffee+state.milk+state.filter+state.ice/.92;const level=Math.min(.94,vol/c.capacity);const y=270-level*140;return `<defs><clipPath id="glassClip"><path d="M235 125 L250 267 Q300 282 350 267 L365 125Z"/></clipPath></defs><path d="M362 150 Q412 140 401 193 Q395 218 355 211" fill="none" stroke="#6c7555" stroke-width="5"/><path d="M235 125 L250 267 Q300 282 350 267 L365 125Z" fill="#fffaf0"/><g clip-path="url(#glassClip)"><rect x="234" y="${y}" width="132" height="160" fill="${state.milk?(state.coffee?'#c49a70':'#ffe8bc'):'#a66a43'}"/>${state.ice?[0,1,2,3].map((v)=>`<rect x="${251+v%2*47}" y="${Math.max(138,y+8)+Math.floor(v/2)*36}" width="29" height="29" rx="6" transform="rotate(${v%2?12:-9} ${266+v%2*47} ${y+23+Math.floor(v/2)*36})" fill="#c5e7e6" fill-opacity=".8" stroke="#89b9bd"/>`).join(''):''}</g><path d="M235 125 L250 267 Q300 282 350 267 L365 125" fill="none" stroke-width="3"/><ellipse cx="300" cy="125" rx="65" ry="12" fill="none"/><path d="M250 144 L258 217" stroke="white" stroke-width="5" opacity=".7"/>`;}
export function scene(step,t,c,before){let art='';let f=Math.min(t*1.5,1);if(step.action in legacy){art=legacyScene(legacy[step.action],t,c);if(step.action==='grind')art=art.replace('摩卡壶研磨 · 不要细成粉末','按当前配方选择研磨粗细');}else{
let state={...before};if(step.add){const key=step.add;state[key]+=(key==='filter'?c.target:c[key])*f;}
art=shadow()+glass(state,c);
if(step.action==='pourMilk'||step.action==='pourCoffee'){const milk=step.action==='pourMilk';art+=`<g transform="translate(-70 -60) scale(.7) rotate(28 292 170)">${pitcher()}</g>${t<.67?`<path d="M218 76 Q273 90 285 177" fill="none" stroke="${milk?'#f1cd91':'#98613e'}" stroke-width="7"/>`:''}`;}
if(['filter','bloom','drip','wait'].includes(step.action)){art+=`<path d="M230 70 H370 L325 128 H275Z" fill="#f4bd8c"/><path d="M242 75 H358 L320 119 H280Z" fill="#fff6df"/><path d="M263 90 H338 L320 119 H280Z" fill="#9c7655"/><path d="M246 78 L280 117 M354 78 L320 117" fill="none"/>`;if(step.action!=='filter')art+=`<path d="M300 128 V${145+Math.sin(t*30)*5}" stroke="#a77650" stroke-width="3"/>`;if(['bloom','drip'].includes(step.action))art+=`<path d="M367 28 Q${280+Math.sin(t*15)*20} 45 ${295+Math.sin(t*15)*20} 90" fill="none" stroke="#8abfc5" stroke-width="5"/>`;}
if(step.action==='ice'&&t<.65)art+=`<rect x="280" y="${45+t*120}" width="27" height="27" rx="5" fill="#b6dfe3" transform="rotate(16 295 70)"/>`;
}
const svg=`<svg viewBox="145 10 310 295" aria-hidden="true">${defs}<ellipse cx="297" cy="180" rx="170" ry="135" fill="#fff1bd" opacity=".65" stroke="none"/><g class="doodle" filter="url(#handdrawn)" stroke="#635940" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${art.replace(/<text[\s\S]*?<\/text>/g,'')}</g><g fill="#d88651" stroke="none"><path d="M160 85 l4 -10 4 10 10 4 -10 4 -4 10 -4 -10 -10 -4Z"/><circle cx="430" cy="220" r="4"/></g></svg>`;
const suffix=++serial;return svg.replace(/id="([^"]+)"/g,'id="$1-'+suffix+'"').replace(/url\(#([^)]+)\)/g,'url(#$1-'+suffix+')');
}
